			$out = array();
			$html = <<<'HTMLX'
<!-- awi-titan-fitur-start --><p style="margin:40px 0 4px;font-size:13px;letter-spacing:2px;text-transform:uppercase;color:#4f7a3a;font-weight:700">Fitur Unggulan · Brosur Resmi</p><h2 style="margin:0 0 10px;font-size:26px;line-height:1.3;color:#111111">6 Fitur Utama BYD TiTAN 7 DM</h2>
<p style="margin:0 0 18px;line-height:1.75;color:#333;font-size:16px">Tagline resminya <em>"Urban Adventure Redefined"</em>: SUV yang nyaman untuk harian di dalam kota Makassar, tapi tetap siap diajak ke jalur pasir, tanjakan, sampai camping akhir pekan. Ini 6 fitur utamanya sesuai brosur resmi BYD Indonesia.</p>
<div style="display:flex;flex-wrap:wrap;gap:16px;margin:0 0 10px">
<div style="flex:1 1 300px;min-width:0"><figure style="margin:0 0 8px"><img src="U10859" alt="BYD TiTAN 7 DM teknologi DM-p 110 kW mesin 360 kW motor 630 Nm 0-100 km/jam 4,8 detik" width="500" height="242" loading="lazy" style="display:block;width:100%;height:auto;border-radius:10px" /></figure><h3 style="margin:0 0 6px;font-size:18px;color:#111">1. Performa Tinggi dengan Teknologi DM-p</h3><p style="margin:0 0 14px;line-height:1.7;color:#333;font-size:15px">Mesin 1.5 Turbo khusus hybrid (110 kW), sistem Electric Hybrid (EHS), dan motor belakang 3-in-1. Total tenaga motor <strong>360 kW</strong>, torsi <strong>630 Nm</strong>, dan 0–100 km/jam cuma <strong>4,8 detik</strong> di varian Performance (AWD DM-p). Mau nyalip di jalan poros atau menanjak, tenaganya gak kurang.</p></div>
<div style="flex:1 1 300px;min-width:0"><figure style="margin:0 0 8px"><img src="U10860" alt="BYD TiTAN 7 DM suspensi DiSus-C mode nyaman atau sport" width="500" height="242" loading="lazy" style="display:block;width:100%;height:auto;border-radius:10px" /></figure><h3 style="margin:0 0 6px;font-size:18px;color:#111">2. Suspensi DiSus-C</h3><p style="margin:0 0 14px;line-height:1.7;color:#333;font-size:15px">Suspensi pintar yang bisa diatur <strong>Comfort</strong> atau <strong>Sport</strong>, sesuai gaya nyetir. Pilih Comfort untuk perjalanan keluarga, misalnya Makassar–Malino atau Makassar–Bulukumba, biar penumpang tetap nyaman. Pilih Sport kalau mau lebih mantap di tikungan.</p></div>
<div style="flex:1 1 300px;min-width:0"><figure style="margin:0 0 8px"><img src="U10861" alt="BYD TiTAN 7 DM mode multi-terrain di jalur pasir" width="500" height="242" loading="lazy" style="display:block;width:100%;height:auto;border-radius:10px" /></figure><h3 style="margin:0 0 6px;font-size:18px;color:#111">3. Multi-Terrain Mode &amp; Crawl (Creep Mode)</h3><p style="margin:0 0 14px;line-height:1.7;color:#333;font-size:15px">Mode khusus <strong>Snow, Mountain, Muddy, dan Sand</strong>, ditambah Creep Mode untuk merayap pelan di medan sulit. Jalan berlumpur, kerikil, atau pasir pantai bisa dilibas dengan lebih percaya diri.</p></div>
<div style="flex:1 1 300px;min-width:0"><figure style="margin:0 0 8px"><img src="U10862" alt="BYD TiTAN 7 DM fitur Leopard U-Turn putar balik 360 derajat" width="500" height="242" loading="lazy" style="display:block;width:100%;height:auto;border-radius:10px" /></figure><h3 style="margin:0 0 6px;font-size:18px;color:#111">4. Leopard U-Turn</h3><p style="margin:0 0 14px;line-height:1.7;color:#333;font-size:15px">Putar balik super rapat ala pivot, bahkan bisa berputar <strong>360°</strong> di tempat. Berguna saat terjebak di jalan sempit, gang buntu, atau jalur offroad yang gak ada ruang untuk putar balik biasa.</p></div>
<div style="flex:1 1 300px;min-width:0"><figure style="margin:0 0 8px"><img src="U10864" alt="BYD TiTAN 7 DM fitur V2L untuk camping" width="500" height="242" loading="lazy" style="display:block;width:100%;height:auto;border-radius:10px" /></figure><h3 style="margin:0 0 6px;font-size:18px;color:#111">5. V2L, Siap Kapan Saja &amp; di Mana Saja</h3><p style="margin:0 0 14px;line-height:1.7;color:#333;font-size:15px">Fitur <strong>Vehicle-to-Load (V2L)</strong> menjadikan mobil sumber listrik untuk alat elektronik: lampu tenda, rice cooker, kipas, sampai laptop. Cocok untuk camping, mancing, atau jualan di acara outdoor. Saat mati lampu di rumah pun bisa jadi cadangan listrik darurat.</p></div>
<div style="flex:1 1 300px;min-width:0"><figure style="margin:0 0 8px"><img src="U10863" alt="BYD TiTAN 7 DM ADAS dan High Speed Tire Burst Assist" width="500" height="242" loading="lazy" style="display:block;width:100%;height:auto;border-radius:10px" /></figure><h3 style="margin:0 0 6px;font-size:18px;color:#111">6. Intelligent Driving Assist</h3><p style="margin:0 0 14px;line-height:1.7;color:#333;font-size:15px">Dilengkapi <strong>20 fitur keselamatan (ADAS)</strong> plus <strong>High Speed Tire Burst Assist</strong>, yang membantu menjaga mobil tetap stabil dan mengerem saat ban pecah hingga kecepatan <strong>140 km/jam</strong>. Perjalanan tol atau jalan poros jadi lebih tenang untuk satu keluarga.</p></div>
</div>
<div style="margin:6px 0 26px;padding:16px 18px;border-radius:12px;background:#f3f7f0;border-left:4px solid #4f7a3a"><p style="margin:0 0 6px;font-size:15px;color:#111"><strong>Harga BYD TiTAN 7 DM Makassar: <span style="display:inline-block;padding:2px 10px;border-radius:20px;background:#111;color:#fff;font-size:13px;letter-spacing:1px">TBA</span></strong> <span style="color:#555">(To Be Announced)</span></p><p style="margin:0;line-height:1.7;color:#333;font-size:15px">Harga resmi segera diumumkan. Daftar inden sekarang supaya dapat info harga pertama dan urutan unit lebih awal, stok terbatas. <a href="https://wa.me/6282259452349?text=Halo%20AWI%2C%20saya%20mau%20daftar%20inden%20BYD%20TiTAN%207%20DM" style="color:#0b5bd3;text-decoration:underline">Chat WhatsApp 0822-5945-2349</a>.</p></div><!-- awi-titan-fitur-end -->
HTMLX;
			$html = preg_replace_callback('#src="U(\d+)"#', function ($m) { return 'src="' . wp_get_attachment_url((int) $m[1]) . '"'; }, $html);
			$c = get_post_field('post_content', 10706); $o = $c;
			$anchor = '<p style="margin:40px 0 4px;font-size:13px;letter-spacing:2px;text-transform:uppercase;color:#4f7a3a;font-weight:700">Pilihan Warna</p>';
			if (strpos($c, 'awi-titan-fitur-start') === false) {
				$i = strpos($c, $anchor);
				$out['anchor'] = $i;
				if ($i !== false) $c = substr($c, 0, $i) . $html . "\n" . substr($c, $i);
			}
			$c = str_replace('Harga resmi Indonesia diumumkan saat peluncuran.', 'Harga: <strong>TBA (To Be Announced)</strong>, diumumkan resmi saat peluncuran.', $c, $n1);
			$c = str_replace('Harga resmi BYD TiTAN 7 DM untuk Indonesia akan diumumkan', 'Harga BYD TiTAN 7 DM saat ini masih <strong>TBA (To Be Announced)</strong>. Harga resmi untuk Indonesia akan diumumkan', $c, $n2);
			$out['n'] = array($n1, $n2);
			$j = strpos($c, 'Harga OTR Makassar</td>');
			if ($j === false) $j = strpos($c, 'Harga OTR Makassar');
			$out['row'] = substr($c, $j, 700);
			if ($c !== $o) { $wpdb->update($wpdb->posts, array('post_content' => $c), array('ID' => 10706)); clean_post_cache(10706); $out['saved'] = 1; }
			update_post_meta(10706, 'rep_fields', array(array('typem' => 'Premium (FWD DM-i)', 'pricem' => 'TBA'), array('typem' => 'Performance (AWD DM-p)', 'pricem' => 'TBA')));
			$t = $wpdb->prefix . 'snippets';
			foreach (array(13, 24) as $sid) {
				$code = $wpdb->get_var($wpdb->prepare("SELECT code FROM $t WHERE id=%d", $sid));
				$nc = str_replace(array('Harga diumumkan saat peluncuran', 'menunggu harga resmi (inden)'), array('Harga TBA (To Be Announced)', 'harga masih TBA (inden)'), $code, $cnt);
				if ($nc !== $code) $wpdb->update($t, array('code' => $nc), array('id' => $sid));
				$out['snip'][$sid] = $cnt;
			}
			$f = 'Code_Snippets' . chr(92) . 'clean_snippets_cache';
			if (function_exists($f)) $f($t);
			wp_cache_flush();
			return $out;
		},
	));
});
